-- How do simple maximum-z thresholds trade off recall and alert volume?
WITH sec AS (SELECT time,MAX(attack) attack,MAX(z_score) max_z FROM scores WHERE split='test' GROUP BY time), thresholds AS (SELECT * FROM (VALUES (2),(3),(4),(5),(8),(10)) t(threshold)) SELECT threshold,COUNT(*) FILTER (WHERE max_z>=threshold) alerts,SUM(attack) FILTER (WHERE max_z>=threshold) attack_seconds_found,ROUND(100.0*SUM(attack) FILTER (WHERE max_z>=threshold)/SUM(attack),2) recall_pct,ROUND(100.0*SUM(attack) FILTER (WHERE max_z>=threshold)/NULLIF(COUNT(*) FILTER (WHERE max_z>=threshold),0),2) alert_precision_pct FROM sec CROSS JOIN thresholds GROUP BY threshold ORDER BY threshold;
